\label{thm:asymptotic-distribution}
Suppose that Assumptions~\ref{ass:A1},~\ref{ass:A2},~\ref{ass:A3},~\ref{ass:A4},~\ref{ass:A5} hold. Then the feasible two-step estimator \eqref{final-elasticity-estimator} is consistent,
\[
    \widehat{\vartheta}_{\varepsilon,n}
    \xrightarrow{\mathbb{P}\text{-prob.}}\vartheta_{0},
\]
and has the first-order limit
\begin{equation}\label{elasticity-limit-variable}
    \varepsilon^{-1}\big(\widehat{\vartheta}_{\varepsilon,n}-\vartheta_{0}\big)\xrightarrow{\mathbb{P}\text{-prob.}}\xi_{\vartheta_{0}}, \quad\text{where}\quad\xi_{\vartheta_{0}}:=-\frac{\nu(1-\vartheta_{0})}{\mu}\frac{\int_{0}^{T}\mathcal{X}_{t}^{3-3\vartheta_{0}}dW_{t}}{\int_{0}^{T}\mathcal{X}_{t}^{4-4\vartheta_{0}}dt}, \quad\mathcal{X}_{t}=x_{0}e^{\mu t}.
\end{equation}
\begin{equation}\label{elasticity-asymptotic-variance}
    \mathcal{L}_{\mathbb{P}}(\xi_{\vartheta_{0}})=\mathcal{N}(0,V_{\vartheta_{0}}),\quad\text{with}\quad V_{\vartheta_{0}}:=\frac{\nu^{2}(1-\vartheta_{0})^{2}\int_{0}^{T}\mathcal{X}_{t}^{6-6\vartheta_{0}}dt}{\mu^{2}\big(\int_{0}^{T}\mathcal{X}_{t}^{4-4\vartheta_{0}}dt\big)^{2}}=\frac{8\nu^{2}(1-\vartheta_{0})^{3}}{-3\mu x_{0}^{2(1-\vartheta_{0})}}\frac{1-e^{6\mu(1-\vartheta_{0})T}}{\big[1-e^{4\mu(1-\vartheta_{0})T}\big]^{2}}.
\end{equation}

\label{rem:estimator-hierarchy}
The argument proceeds from the auxiliary CIR oracle under $\mathbb{Q}^{\varepsilon}$ to the same estimator under $\mathbb{P}$, then replaces the auxiliary CKLS path by the observed CEV path and the unknown elasticity $\vartheta_{0}$ by its preliminary estimate. Appendix~\ref{aaa} justifies the measure transfer, and Appendix~\ref{bbb} proves the oracle limit and the two approximation bounds: $\widehat{\beta}_{\varepsilon,n}^{Y,\circ}
    \text{ under }\mathbb{Q}^{\varepsilon}\to
    \widehat{\beta}_{\varepsilon,n}^{Y,\circ}
    \text{ under }\mathbb{P}\to
    \widehat{\beta}_{\varepsilon,n}^{X,\circ}
    \text{ under }\mathbb{P}\to
    \widehat{\beta}_{\varepsilon,n}
    \text{ under }\mathbb{P}$.

\label{thm:general-ckls-cir}
Let $Y$ be the CKLS process with $a,b,\sigma,y_{0}>0$ and $k\in(1/2,1)$, and fix $T<\infty$ and $\zeta>0$. Under the equivalent measure $\mathbb{Q}$ constructed above, $\widetilde{W}$ is a standard Brownian motion, and $Z_{t}^{(k)}:=\mathcal{T}(Y_{t};k)$ by \eqref{state-mapping-general-form} satisfies
\begin{equation}\label{general-cir-transformed}
	dZ_{t}^{(k)}=\Big[\frac{\sigma^{2}\zeta^{2}}{2}-2b(1-k)Z_{t}^{(k)}\Big]dt+\sigma\zeta\sqrt{Z_{t}^{(k)}}d\widetilde{W}_{t},\qquad Z_{0}^{(k)}=\mathcal{T}(y_{0};k)>0.
\end{equation}

\label{rem:why-Local-to-CEV-scaling}
The additional drift $a_{\varepsilon}=\varepsilon^{2}a^{*}$ regularizes the $0$ boundary by keeping the auxiliary CKLS process strictly positive for each $\varepsilon>0$, while preserving the first-order small-noise behavior of the target CEV process; see \eqref{process-level-estiamte}. The common factor $\varepsilon$ in the Girsanov kernel and the uniform inverse-moment bound yield the $O(\varepsilon^{2})$ energy estimate in Theorem~\ref{thm:total-variation-closeness}. The same scaling supports the uniform inverse-moment estimate: in the generator applied to $y^{-r}$, the negative regularization term and the positive It\^{o} correction both carry a factor $\varepsilon^{2}$, while the former is more singular near $0$ because $\vartheta_{0}>1/2$. 

More generally, $a_{\varepsilon}=\varepsilon^{p}a^{*}$ with $p>1$ lies below the first-order small-noise scale and yields Girsanov kernel contributions of orders $\varepsilon^{p-1}$ and $\varepsilon$ on compact subsets of $(0,\infty)$. We choose $p=2$ to match these orders. By contrast, $a_{\varepsilon}=\varepsilon a^{*}$ produces an order-one contribution to the kernel on compact subsets of $(0,\infty)$ and enters the first-order fluctuation dynamics. Vanishing energy, and hence total-variation closeness, is therefore no longer guaranteed by the present argument. A fixed $a>0$ would change the deterministic small-noise limit, so the auxiliary-to-CEV approximation and common deterministic limit in Lemmas~\ref{lem:local-to-CEV-process-approx} and~\ref{lem:uniform-deterministic-limit} would no longer hold. It would also contribute a term of order $\varepsilon^{-1}$ to the kernel on such compact sets.

\label{lem:auxiliary-pseudo-cir-bounds}
Let $Z^{Y,\varepsilon,\circ}$ be the auxiliary pseudo-CIR process satisfying
\[
    \text{\eqref{auxiliary-oracle-cir-dynamics}. Then}\sup_{0<\varepsilon\le\varepsilon_{0}}\sup_{0\leq u\leq T}\mathbb{E}^{\mathbb{Q}^{\varepsilon}}\big[Z_{u}^{Y,\varepsilon,\circ}+\big(Z_{u}^{Y,\varepsilon,\circ}\big)^{2}+\big(Z_{u}^{Y,\varepsilon,\circ}\big)^{3}\big]<\infty.\text{ Moreover, there exists some $C>0$ such that}
\]
\begin{equation}\label{auxiliary-oracle-increment-estimate-general}
    \mathbb{E}^{\mathbb{Q}^{\varepsilon}}\big[|Z_{u}^{Y,\varepsilon,\circ}-Z_{s}^{Y,\varepsilon,\circ}|^{2}\big]\leq C\big[|u-s|^{2}+\varepsilon^{2}|u-s|\big],\qquad 0\leq s\leq u\leq T.
\end{equation}

\label{lem:CEV-holder-continuity}
Let $X^{\varepsilon,\vartheta_{0}}$ be the target CEV process with fixed $\vartheta_{0}\in(1/2,1)$. Let $\Phi_{n}(\vartheta)=(e^{2\mu\vartheta h_{n}}-1)/(2\mu\vartheta h_{n})$. Under Assumption~\ref{ass:A4}, as $\varepsilon\to0$ and $n\to\infty$,
\begin{equation}\label{local-window-approximation-rate}
    \frac{1}{h_{n}}\int_{\tau_{n}}^{\tau_{n}'}\big(X_{s}^{\varepsilon,\vartheta_{0}}\big)^{2\vartheta_{0}}ds-\big(X_{\tau_{n}}^{\varepsilon,\vartheta_{0}}\big)^{2\vartheta_{0}}\Phi_{n}(\vartheta_{0})=O_{\mathbb{P}}\big(\varepsilon\sqrt{h_{n}}\big).
\end{equation}

\label{lem:local-RV-QV-approximation}
Recall that
\[
	\widehat{\mathcal{V}}_{\varepsilon,n}:=\sum_{i=j_{n}+1}^{j_{n}+m_{n}}\Big(X_{t_{i}}^{\varepsilon,\vartheta_{0}}-X_{t_{i-1}}^{\varepsilon,\vartheta_{0}}\Big)^{2},\quad\text{where}\quad j_{n}:=\lfloor\tau/\Delta_{n}\rfloor, \quad\tau_{n}=t_{j_{n}},\quad h_{n}=m_{n}\Delta_{n}, \quad\tau'_{n}:=\tau_{n}+h_{n}\leq T.
\]
Under Assumptions~\ref{ass:A1},~\ref{ass:A2},~\ref{ass:A4}
\begin{equation}\label{local-RV-QV-full-rate}
    \frac{\widehat{\mathcal{V}}_{\varepsilon,n}-\big\{[X^{\varepsilon,\vartheta_{0}}]_{\tau'_{n}}-[X^{\varepsilon,\vartheta_{0}}]_{\tau_{n}}\big\}}{\varepsilon^{2}\nu^{2}h_{n}}=O_{\mathbb{P}}\Big(\sqrt{\frac{\Delta_{n}}{h_{n}}}+\frac{\Delta_{n}}{\varepsilon\sqrt{h_{n}}}+\frac{\Delta_{n}}{\varepsilon^{2}}\Big).
\end{equation}
